package vn.edu.webpro.robotlab.controller;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import vn.edu.webpro.robotlab.dao.*;import vn.edu.webpro.robotlab.model.AssemblyStep;import vn.edu.webpro.robotlab.web.*;
@WebServlet("/api/admin/steps/*") public final class AdminStepServlet extends HttpServlet{private final AssemblyStepDao steps=new AssemblyStepDao(new DatabaseConnectionFactory(System.getenv()));@Override protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{if(AdminAccess.requireAdmin(q,p)==null)return;try{var data=steps.list(100,0);String json=data.stream().map(AssemblyStep::toJson).reduce((a,b)->a+","+b).orElse("");ApiResponses.json(p,200,"{\"data\":["+json+"],\"meta\":{\"page\":1,\"limit\":100,\"total\":"+data.size()+"}}");}catch(SQLException e){ApiResponses.error(p,503,"DEPENDENCY_NOT_READY","Cơ sở dữ liệu chưa được cấu hình.");}}@Override protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{write(q,p,null,true);}@Override protected void doDelete(HttpServletRequest q,HttpServletResponse p)throws IOException{if(AdminAccess.requireAdmin(q,p)==null||!AdminAccess.requireCsrf(q,p))return;try{if(!steps.remove(id(q))){ApiResponses.error(p,404,"NOT_FOUND","Không tìm thấy nội dung.");return;}p.setStatus(204);}catch(SQLException e){ApiResponses.error(p,409,"RELATION_CONFLICT","Không thể xóa bước đang được sử dụng.");}}@Override protected void service(HttpServletRequest q,HttpServletResponse p)throws javax.servlet.ServletException,IOException{if("PATCH".equals(q.getMethod())){write(q,p,id(q),false);return;}super.service(q,p);}private void write(HttpServletRequest q,HttpServletResponse p,String old,boolean add)throws IOException{if(AdminAccess.requireAdmin(q,p)==null||!AdminAccess.requireCsrf(q,p))return;try{String b=q.getReader().lines().reduce("",(a,c)->a+c);AssemblyStep s=input(b,add?null:old);AssemblyStep saved=add?steps.create(s):steps.update(old,s);if(saved==null){ApiResponses.error(p,404,"NOT_FOUND","Không tìm thấy nội dung.");return;}ApiResponses.json(p,add?201:200,"{\"data\":"+saved.toJson()+"}");}catch(IllegalArgumentException e){ApiResponses.error(p,422,"VALIDATION_ERROR","Dữ liệu bước lắp ráp không hợp lệ.");}catch(SQLException e){ApiResponses.error(p,409,"CONFLICT","Không thể lưu bước lắp ráp.");}}private String id(HttpServletRequest q){return q.getPathInfo()==null?"":q.getPathInfo().substring(1);}private AssemblyStep input(String b,String old){String id=old==null?Json.stringField(b,"id").trim():old,robot=Json.stringField(b,"robotId").trim(),title=Json.stringField(b,"title").trim(),instruction=Json.stringField(b,"instruction").trim(),image=Json.objectField(b,"illustration");int order=Integer.parseInt(Json.stringField(b,"stepOrder"));if(!id.matches("[a-z0-9]+(?:-[a-z0-9]+)*")||!robot.matches("[a-z0-9]+(?:-[a-z0-9]+)*")||order<1||title.isEmpty()||instruction.isEmpty())throw new IllegalArgumentException();return new AssemblyStep(id,robot,order,title,instruction,image);}}
